            bool permissionsRefs,
            bool productPriceHistoryRefs,
            bool invoicesRefs,
            bool suspendedInvoicesRefs,
            bool purchaseInvoicesRefs,
            bool stockMovementsRefs,
            bool inventoryCountsRefs,
            bool treasuryTransactionsRefs,
            bool shiftsRefs,
            bool auditLogRefs,
            bool salesReturnsRefs,
            bool purchaseReturnsRefs,
          })
        > {
  $$UsersTableTableManager(_$AppDatabase db, $UsersTable table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$UsersTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$UsersTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$UsersTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<int> id = const Value.absent(),
                Value<String> username = const Value.absent(),
                Value<String> passwordHash = const Value.absent(),
                Value<String> fullName = const Value.absent(),
                Value<String> role = const Value.absent(),
                Value<bool> isActive = const Value.absent(),
                Value<DateTime> createdAt = const Value.absent(),
              }) => UsersCompanion(
                id: id,
                username: username,
                passwordHash: passwordHash,
                fullName: fullName,
                role: role,
                isActive: isActive,
                createdAt: createdAt,
              ),
          createCompanionCallback:
              ({
                Value<int> id = const Value.absent(),
                required String username,
                required String passwordHash,
                required String fullName,
                required String role,
                Value<bool> isActive = const Value.absent(),
                Value<DateTime> createdAt = const Value.absent(),
              }) => UsersCompanion.insert(
                id: id,
                username: username,
                passwordHash: passwordHash,
                fullName: fullName,
                role: role,
                isActive: isActive,
                createdAt: createdAt,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) =>
                    (e.readTable(table), $$UsersTableReferences(db, table, e)),
              )
              .toList(),
          prefetchHooksCallback:
              ({
                permissionsRefs = false,
                productPriceHistoryRefs = false,
                invoicesRefs = false,
                suspendedInvoicesRefs = false,
                purchaseInvoicesRefs = false,
                stockMovementsRefs = false,
                inventoryCountsRefs = false,
                treasuryTransactionsRefs = false,
                shiftsRefs = false,
                auditLogRefs = false,
                salesReturnsRefs = false,
                purchaseReturnsRefs = false,
              }) {
                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [
                    if (permissionsRefs) db.permissions,
                    if (productPriceHistoryRefs) db.productPriceHistory,
                    if (invoicesRefs) db.invoices,
                    if (suspendedInvoicesRefs) db.suspendedInvoices,
                    if (purchaseInvoicesRefs) db.purchaseInvoices,
                    if (stockMovementsRefs) db.stockMovements,
                    if (inventoryCountsRefs) db.inventoryCounts,
                    if (treasuryTransactionsRefs) db.treasuryTransactions,
                    if (shiftsRefs) db.shifts,
                    if (auditLogRefs) db.auditLog,
                    if (salesReturnsRefs) db.salesReturns,
                    if (purchaseReturnsRefs) db.purchaseReturns,
                  ],
                  addJoins: null,
                  getPrefetchedDataCallback: (items) async {
                    return [
                      if (permissionsRefs)
                        await $_getPrefetchedData<
                          User,
                          $UsersTable,
                          Permission
                        >(
                          currentTable: table,
                          referencedTable: $$UsersTableReferences
                              ._permissionsRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $$UsersTableReferences(
                                db,
                                table,
                                p0,
                              ).permissionsRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.userId == item.id,
